-- State transitions declared for TemporaryPermission (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION sapiens.temporary_permissions_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'active'), ('active', 'expired'), ('active', 'revoked'), ('pending', 'active'), ('pending', 'revoked'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: temporary_permissions.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS temporary_permissions_status_transition_check ON sapiens.temporary_permissions;
CREATE TRIGGER temporary_permissions_status_transition_check
    BEFORE UPDATE OF "status" ON sapiens.temporary_permissions
    FOR EACH ROW EXECUTE FUNCTION sapiens.temporary_permissions_status_transition_check();
